function generate(rand, size) {
  const fridays = [3, 10, 17, 24], near = [2, 3, 4, 9, 10, 11, 16, 17, 18, 23, 24, 25, 30, 1];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const users = size === 'small' ? 5 : 400;
  const seen = new Set(), Purchases = [];
  for (let i = 0; i < count; i++) {
    // Small sets favour Fridays and the days around them, so some Fridays stay empty; large sets use any November day.
    const r = rand();
    const day = size === 'small' ? (r < 0.4 ? fridays[Math.floor(rand() * 4)] : near[Math.floor(rand() * near.length)]) : 1 + Math.floor(r * 30);
    const user = 1 + Math.floor(rand() * users);
    const amount = size === 'small' ? 100 * (1 + Math.floor(rand() * 20)) : 1 + Math.floor(rand() * 12000);
    const date = `2023-11-${String(day).padStart(2, '0')}`, key = `${user}|${date}|${amount}`;
    if (seen.has(key)) continue;
    seen.add(key);
    Purchases.push([user, date, amount]);
  }
  return [{ Purchases }];
}
